/**
 * A batch of local changes ready for `push_ops`. `payload` is already
 * encrypted and base64-encoded; the app sends it as-is and calls
 * `push_succeeded` with the same `batch_id` once the server accepts it.
 * Retrying after a failure returns the same batch with the same id, so the
 * server's idempotency check makes a retried push harmless.
 */
public struct OutgoingBatch: Equatable, Hashable {
    public var batchId: String
    public var payload: String
    public var opCount: UInt32

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(batchId: String, payload: String, opCount: UInt32) {
        self.batchId = batchId
        self.payload = payload
        self.opCount = opCount
    }

    

    
}

#if compiler(>=6)
extension OutgoingBatch: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeOutgoingBatch: FfiConverterRustBuffer {
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> OutgoingBatch {
        return
            try OutgoingBatch(
                batchId: FfiConverterString.read(from: &buf), 
                payload: FfiConverterString.read(from: &buf), 
                opCount: FfiConverterUInt32.read(from: &buf)
        )
    }

    public static func write(_ value: OutgoingBatch, into buf: inout [UInt8]) {
        FfiConverterString.write(value.batchId, into: &buf)
        FfiConverterString.write(value.payload, into: &buf)
        FfiConverterUInt32.write(value.opCount, into: &buf)
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeOutgoingBatch_lift(_ buf: RustBuffer) throws -> OutgoingBatch {
    return try FfiConverterTypeOutgoingBatch.lift(buf)
}

