public enum BlockKind: Equatable, Hashable {
    
    case paragraph
    case heading(level: UInt8
    )
    case bullet
    case numbered
    case check(checked: Bool
    )
    case quote
    case code
    case rule
    /**
     * An attachment shown inline; `text` is its caption.
     */
    case image(attachmentId: String
    )





}

#if compiler(>=6)
extension BlockKind: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBlockKind: FfiConverterRustBuffer {
    typealias SwiftType = BlockKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BlockKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .paragraph
        
        case 2: return .heading(level: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 3: return .bullet
        
        case 4: return .numbered
        
        case 5: return .check(checked: try FfiConverterBool.read(from: &buf)
        )
        
        case 6: return .quote
        
        case 7: return .code
        
        case 8: return .rule
        
        case 9: return .image(attachmentId: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BlockKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case .paragraph:
            writeInt(&buf, Int32(1))
        
        
        case let .heading(level):
            writeInt(&buf, Int32(2))
            FfiConverterUInt8.write(level, into: &buf)
            
        
        case .bullet:
            writeInt(&buf, Int32(3))
        
        
        case .numbered:
            writeInt(&buf, Int32(4))
        
        
        case let .check(checked):
            writeInt(&buf, Int32(5))
            FfiConverterBool.write(checked, into: &buf)
            
        
        case .quote:
            writeInt(&buf, Int32(6))
        
        
        case .code:
            writeInt(&buf, Int32(7))
        
        
        case .rule:
            writeInt(&buf, Int32(8))
        
        
        case let .image(attachmentId):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(attachmentId, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeBlockKind_lift(_ buf: RustBuffer) throws -> BlockKind {
    return try FfiConverterTypeBlockKind.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeBlockKind_lower(_ value: BlockKind) -> RustBuffer {
    return FfiConverterTypeBlockKind.lower(value)
}



/**
 * Every error the core hands to the apps. Messages are for logs, not for
 * showing to users; the variant is what the UI branches on.
 */
public 
enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Database(message: String)
    
    case NotFound(message: String)
    
    case Invalid(message: String)
    
    case Sync(message: String)
    
    case Crypto(message: String)
    

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension CoreError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Database(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .NotFound(
